#pragma once
#include <raylib.h>

// Registry of EMBEDDED fonts, addressed by name: no file to find at runtime, hence identical
// rendering on every target, WASM included. The atlases are generated by tools/gen_ui_font.cpp,
// through raylib's ExportFontAsCode.
//
// "sans" and "mono" are SIGNED DISTANCE FIELDS: they stay sharp at any size, which a bitmap atlas
// stretched to ten times its size does not. They need a shader to be read, so text is drawn through
// engine_draw_text, never through DrawTextEx directly; "pixel" is a plain bitmap and needs nothing.
//
// Shared by `graphics` (the current font for text calls) and by `ui` (widget labels), so that an
// atlas is loaded only once.

int engine_font_count();
const char* engine_font_name(int idx);
// Returns -1 for an unknown name, leaving the error message to the caller.
int engine_font_index(const char* name);
// The font is loaded on FIRST use: building its atlas creates a texture, which requires a
// graphics context. Falls back to GetFontDefault() on failure.
Font engine_font(int idx);
// False while there is no drawing area: no font is loaded then, and nothing can be measured or drawn.
bool engine_font_usable(int idx);
// Measure and draw take the font by INDEX and a size in pixels: the spacing (size / the atlas's own size)
// and the shader a signed distance field needs are the registry's business, so a measure and the drawing
// it is meant to match cannot disagree. The caller checks engine_font_usable first.
Vector2 engine_text_size(int idx, const char* text, float size);
void engine_draw_text(int idx, const char* text, Vector2 pos, float size, Color color);
// A signed distance field is read by a shader, and switching shader empties rlgl's batch: so the shader
// stays BOUND after a text, and a run of texts and shapes is one draw call. The contract: close the run
// before drawing anything that is not an SDF text or a plain shape (a sprite's soft alpha would be cut at
// one half). `with_area` (graphics_internal.h) does it for every graphics function unless declared safe;
// the bitmap font and the engine's frame boundaries do it by themselves. Cheap when nothing is open.
void engine_text_run_end();
// Forgets the fonts WITHOUT unloading them: their textures belong to the previous program's
// context, which is already destroyed. Called when a program starts.
void engine_font_reset();

// Index of the default font, the registry entry named "sans".
int engine_font_default();

// Distance from the top of a line down to its BASELINE, at the size asked for. raylib's Font does
// not carry it, so it is a metric of the REGISTRY rather than of any one caller: `graphics` aligns
// text on it, and `ui` will the day a widget label has to.
// Precondition: engine_font_usable(idx).
float engine_font_ascent(int idx, float size);
